from typing import List

def criticalConnections(V: int, adj: List[List[int]]) -> List[List[int]]:
    discovery = [0] * V
    low = [0] * V
    time = 1
    result = []

    def dfs(u, parent):
        nonlocal time
        discovery[u] = low[u] = time
        time += 1
        for v in adj[u]:
            if v == parent:
                continue
            if discovery[v] == 0:
                dfs(v, u)
